css:
/* Layout: broadcast package, night game only. Sticky score bar with live section chips, a lower-third
   hero with a telestrator ring, an "in this issue" jump grid, ticker-code team badges, and the yellow
   first-down line wherever a line decided something. */
:root {
  color-scheme: dark;
  --bg: #0A1220; --surface: #101B2D; --surface-2: #17243A; --ink: #EAF0F7; --ink-2: #9BA9BD; --rule: #22314A;
  --pylon: #FF6A1F; --pylon-ink: #FF8A4C; --on-pylon: #0A1220;
  --firstdown: #FFD60A; --on-firstdown: #0A1220;
  --win: #3DD68C; --loss: #FF7070;
  --bar: #EAF0F7; --bar-loss: #5D6D85; --ghost: #33445F;
  --m-jugg: #3DD68C; --m-cont: #8FE3B5; --m-allin: #FF6A1F; --m-rebuild: #5BA4E6; --m-tank: #8C9AB0; --m-mixed: #C4B5FD;
  --tier-s: #FF6A1F; --tier-a: #FFA23A; --tier-b: #FFD60A; --tier-c: #8FE3B5; --tier-d: #5BA4E6; --tier-ass: #8B6B4A; --tier-mega: #6B4C31; --tier-super: #4A3221;
  --t1: #7C8CFF; --t2: #B07CFF; --t3: #E07A9A; --t4: #4FB3BF; --t5: #E8604C; --t6: #5BA4E6; --t7: #D2B271; --t8: #9CC24A; --t9: #B08463; --t10: #A6AFC0;
  --display: "Anybody", "Arial Narrow", "Roboto Condensed", sans-serif;
  --body: "Instrument Sans", system-ui, -apple-system, "Segoe UI", sans-serif;
  --mono: "Martian Mono", ui-monospace, "SF Mono", Menlo, monospace;
}
:root[data-theme="light"] {
  color-scheme: light;
  --bg: #F6F2EA; --surface: #FFFFFF; --surface-2: #EEE8DC; --ink: #141B29; --ink-2: #5A6578; --rule: #D9D2C4;
  --pylon: #E85A12; --pylon-ink: #C94B0C; --on-pylon: #FFFFFF;
  --firstdown: #E6B800; --on-firstdown: #141B29;
  --win: #178A52; --loss: #C8322E;
  --bar: #141B29; --bar-loss: #9AA4B5; --ghost: #C9CFD9;
  --m-jugg: #178A52; --m-cont: #2E9E6C; --m-allin: #E85A12; --m-rebuild: #2F7FC1; --m-tank: #6C7A90; --m-mixed: #7C5CC9;
  --tier-c: #2E9E6C; --tier-d: #2F7FC1;
}
:root[data-theme="light"] img.piece, :root[data-theme="light"] .tb { filter: none; }
.theme-toggle { display: inline-flex; align-items: center; gap: 6px; min-height: 36px; padding: 4px 10px; border: 1px solid var(--rule); border-radius: 999px; background: var(--surface); color: var(--ink-2); font-family: var(--mono); font-size: 0.68rem; letter-spacing: 0.06em; text-transform: uppercase; cursor: pointer; }
.theme-toggle i { width: 14px; height: 14px; border-radius: 50%; background: var(--ink); box-shadow: inset -4px -3px 0 0 var(--bg); }
:root[data-theme="light"] .theme-toggle i { box-shadow: none; background: var(--firstdown); }
.theme-toggle:focus-visible { outline: 3px solid var(--firstdown); outline-offset: 2px; }
* { box-sizing: border-box; }
html { scroll-behavior: smooth; scroll-padding-top: 120px; }
body { background: var(--bg); color: var(--ink); font-family: var(--body); font-size: 16px; line-height: 1.6; padding-block: 0 72px; }
body::before { content: ""; position: fixed; inset: 0 0 auto; height: env(safe-area-inset-top, 0px); z-index: 30; background: var(--bg); }
.gut { padding-left: max(16px, env(safe-area-inset-left, 0px)); padding-right: max(16px, env(safe-area-inset-right, 0px)); }
.wrap { max-width: 1120px; margin: 0 auto; }
a { color: inherit; }
a:focus-visible { outline: 3px solid var(--firstdown); outline-offset: 2px; border-radius: 4px; }
p { margin: 0 0 14px; }
.mono { font-family: var(--mono); font-size: 0.72rem; font-weight: 500; letter-spacing: 0.06em; text-transform: uppercase; font-stretch: 90%; }
.num { font-variant-numeric: tabular-nums; }
.dim { color: var(--ink-2); }

/* Team badge: ticker code in the team's color */
.tb { flex: none; display: inline-grid; place-items: center; min-width: 40px; height: 26px; padding-inline: 6px; background: var(--c); color: var(--on-pylon); font-family: var(--display); font-weight: 800; font-stretch: 85%; font-size: 0.82rem; letter-spacing: 0.03em; clip-path: polygon(0 0, 100% 0, 100% 70%, 85% 100%, 0 100%); }
.tb.lg { min-width: 64px; height: 40px; font-size: 1.15rem; }
.mode { flex: none; display: inline-flex; align-items: center; gap: 6px; font-family: var(--mono); font-size: 0.64rem; font-weight: 600; letter-spacing: 0.06em; text-transform: uppercase; color: var(--ink); }
.mode::before { content: ""; width: 8px; height: 8px; border-radius: 50%; background: var(--mc); }
.sil { flex: none; width: 36px; height: 36px; border-radius: 50%; background: var(--surface-2); display: grid; place-items: center; overflow: hidden; }
.sil svg { width: 30px; height: 30px; margin-top: 6px; }
.sil svg * { fill: var(--ink-2); }

/* Score bar */
.bar { position: sticky; top: env(safe-area-inset-top, 0px); z-index: 20; background: var(--bg); border-bottom: 1px solid var(--rule); }
.bar .wrap { display: flex; align-items: center; gap: 10px 20px; padding-block: 10px 8px; flex-wrap: wrap; }
.brand { display: flex; align-items: center; gap: 10px; text-decoration: none; }
.brand .mark { background: var(--pylon); color: var(--on-pylon); font-family: var(--display); font-weight: 900; font-style: italic; font-stretch: 80%; font-size: 1.05rem; line-height: 1; padding: 6px 8px 5px; letter-spacing: 0.02em; }
.brand .word { font-family: var(--display); font-weight: 800; font-stretch: 70%; font-size: 1.35rem; text-transform: uppercase; line-height: 1; letter-spacing: 0.01em; }
.status { margin-left: auto; display: flex; align-items: center; gap: 8px; color: var(--ink-2); }
.status .live { width: 8px; height: 8px; border-radius: 50%; background: var(--win); }
.chipwrap { flex-basis: 100%; min-width: 0; width: 100%; position: relative; }
.chipwrap::after { content: ""; position: absolute; top: 0; right: 0; bottom: 0; width: 28px; background: linear-gradient(90deg, transparent, var(--bg)); pointer-events: none; }
.chips { display: flex; gap: 6px; overflow-x: auto; scrollbar-width: none; padding: 2px 28px 4px 2px; }
.chips::-webkit-scrollbar { display: none; }
.chips a { flex: none; display: inline-flex; align-items: center; min-height: 36px; text-decoration: none; padding: 0 14px; border: 1px solid var(--rule); border-radius: 999px; color: var(--ink-2); background: var(--surface); }
.chips a:hover { color: var(--ink); border-color: var(--ink-2); }
.chips a[aria-current="true"] { background: var(--ink); color: var(--bg); border-color: var(--ink); }
.totop { position: fixed; right: calc(16px + env(safe-area-inset-right, 0px)); bottom: calc(16px + env(safe-area-inset-bottom, 0px)); z-index: 25; width: 48px; height: 48px; display: grid; place-items: center; background: var(--pylon); color: var(--on-pylon); text-decoration: none; font-family: var(--mono); font-weight: 700; font-size: 0.66rem; letter-spacing: 0.06em; clip-path: polygon(0 0, 100% 0, 100% 72%, 78% 100%, 0 100%); }

/* Hero */
.hero { padding-block: 40px 28px; }
.kicker { display: inline-flex; align-items: stretch; margin-bottom: 18px; flex-wrap: wrap; }
.kicker span { padding: 5px 10px; }
.kicker .k1 { background: var(--pylon); color: var(--on-pylon); font-weight: 600; }
.kicker .k2 { background: var(--surface-2); color: var(--ink); }
h1 { font-family: var(--display); font-weight: 900; font-style: italic; font-stretch: 62%; text-transform: uppercase; font-size: clamp(3.4rem, 11.5vw, 8rem); line-height: 0.92; letter-spacing: -0.005em; margin: 0 0 22px; text-wrap: balance; }
.ring { position: relative; display: inline-block; white-space: nowrap; }
.ring svg { position: absolute; left: -13%; top: -42%; width: 126%; height: 184%; overflow: visible; pointer-events: none; }
.ring path { fill: none; stroke: var(--firstdown); stroke-width: 5; stroke-linecap: round; stroke-dasharray: 1; stroke-dashoffset: 0; animation: draw 0.9s 0.35s cubic-bezier(.6,.05,.3,1) backwards; }
@keyframes draw { from { stroke-dashoffset: 1; } to { stroke-dashoffset: 0; } }
.hero-row { display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 440px); gap: 24px 48px; align-items: start; }
.deck { font-size: 1.2rem; line-height: 1.5; max-width: 33em; margin: 0; text-wrap: pretty; }
.deck b { color: var(--pylon-ink); font-weight: 600; }
.race { background: var(--surface); border: 1px solid var(--rule); padding: 18px 18px 16px; min-width: 0; }
.race h3 { font-family: var(--display); font-weight: 800; font-stretch: 75%; text-transform: uppercase; font-size: 1.3rem; line-height: 1.05; margin: 6px 0 16px; }
.lane { display: grid; grid-template-columns: auto minmax(0, 1fr) auto; gap: 6px 10px; align-items: center; margin-bottom: 14px; }
.lane .who { font-weight: 600; min-width: 0; overflow-wrap: break-word; }
.lane .val { font-family: var(--display); font-weight: 800; font-stretch: 80%; font-size: 1.5rem; line-height: 1; }
.track { grid-column: 1 / -1; position: relative; height: 18px; background: var(--surface-2); }
.fill { position: absolute; inset: 0 auto 0 0; width: var(--a); background: var(--bar); }
.fill.l { background: var(--bar-loss); }
.ghost { position: absolute; top: 0; bottom: 0; left: var(--a); width: calc(var(--o) - var(--a)); background: repeating-linear-gradient(135deg, var(--ghost) 0 4px, transparent 4px 8px); outline: 1px dashed var(--ink-2); outline-offset: -1px; }
.needle { position: absolute; top: -6px; bottom: -6px; left: var(--n); width: 3px; margin-left: -1.5px; background: var(--firstdown); }
.race .foot { display: flex; justify-content: space-between; gap: 6px 12px; flex-wrap: wrap; color: var(--ink-2); padding-top: 8px; border-top: 1px solid var(--rule); }
.race .foot b { color: var(--firstdown); font-weight: 600; }
@media (max-width: 860px) { .hero-row { grid-template-columns: 1fr; } }

/* Comments */
.cmts { background: var(--surface); border: 1px solid var(--rule); border-top: 6px solid var(--pylon); padding: 22px 22px 24px; display: grid; gap: 18px; }
.cmts .pick { display: grid; gap: 8px; }
.cmts .pick > span { font-family: var(--mono); font-size: 0.7rem; font-weight: 600; letter-spacing: 0.08em; text-transform: uppercase; color: var(--ink-2); }
.cmts select { width: 100%; min-height: 48px; background: var(--bg); color: var(--ink); border: 1px solid var(--rule); padding: 10px 40px 10px 14px; font: inherit; font-size: 16px; font-weight: 600; border-radius: 0; appearance: none; -webkit-appearance: none; background-image: linear-gradient(45deg, transparent 50%, var(--ink-2) 50%), linear-gradient(135deg, var(--ink-2) 50%, transparent 50%); background-position: calc(100% - 20px) 50%, calc(100% - 14px) 50%; background-size: 6px 6px; background-repeat: no-repeat; }
.cmts .tb.anon { --c: var(--ink-2); }
.cmts .teams button { display: inline-flex; align-items: center; gap: 8px; min-height: 40px; padding: 4px 12px 4px 6px; background: var(--bg); color: var(--ink); border: 2px solid var(--rule); border-radius: 999px; font: inherit; font-size: 0.9rem; font-weight: 600; cursor: pointer; }
.cmts .teams button[aria-pressed="true"] { border-color: var(--pylon); box-shadow: 0 0 0 1px var(--pylon) inset; }
.cmts form { display: grid; gap: 10px; }
.cmts textarea { width: 100%; background: var(--bg); color: var(--ink); border: 1px solid var(--rule); padding: 12px 14px; font-family: var(--body); font-size: 16px; line-height: 1.5; border-radius: 0; min-height: 84px; resize: vertical; }
.cmts .row { display: flex; justify-content: space-between; align-items: center; gap: 12px; flex-wrap: wrap; }
.cmts .row .as { color: var(--ink-2); font-size: 0.9rem; }
.cmts button[type=submit] { min-height: 46px; padding: 0 22px; background: var(--pylon); color: var(--on-pylon); border: 0; font-family: var(--display); font-weight: 900; font-size: 1.05rem; text-transform: uppercase; letter-spacing: 0.04em; cursor: pointer; }
.cmts button[type=submit]:disabled { opacity: 0.55; cursor: default; }
.cmts .msg { margin: 0; font-size: 0.9rem; color: var(--ink-2); min-height: 1.2em; }
.cmts .msg.err { color: var(--loss); } .cmts .msg.ok { color: var(--win); }
.cmts .list { display: grid; gap: 10px; border-top: 1px solid var(--rule); padding-top: 16px; }
.cmts .c { display: grid; grid-template-columns: auto minmax(0, 1fr); gap: 4px 12px; align-items: start; }
.cmts .c .hd { grid-column: 2; display: flex; gap: 10px; align-items: baseline; flex-wrap: wrap; }
.cmts .c .hd b { font-weight: 700; } .cmts .c .hd time { color: var(--ink-2); font-size: 0.8rem; }
.cmts .c .tb { grid-row: 1; grid-column: 1; margin-top: 2px; justify-self: start; }
.cmts .c p { grid-column: 2; margin: 0; white-space: pre-wrap; overflow-wrap: anywhere; }
.cmts .empty { color: var(--ink-2); font-style: italic; }
.cmts .count { color: var(--ink-2); }

/* Collapsible sections */
.cmchip { display: inline-flex; align-items: center; gap: 6px; min-height: 30px; padding: 2px 10px; border: 1px solid var(--rule); border-radius: 999px; background: var(--surface); color: var(--ink-2); text-decoration: none; font-family: var(--mono); font-size: 0.7rem; font-weight: 600; letter-spacing: 0.06em; text-transform: uppercase; white-space: nowrap; }
.cmchip:hover { border-color: var(--pylon); color: var(--ink); }
.fold { border-top: 1px solid var(--rule); margin-top: 28px; }
.fold summary { list-style: none; cursor: pointer; display: flex; align-items: center; justify-content: space-between; gap: 12px; min-height: 64px; padding: 14px 0; }
.fold summary::-webkit-details-marker { display: none; }
.fold summary .ft { font-family: var(--display); font-weight: 900; text-transform: uppercase; font-size: clamp(1.6rem, 4.6vw, 2.2rem); line-height: 1; }
.fold summary .mono { color: var(--ink-2); display: inline-flex; align-items: center; gap: 8px; }
.fold summary .mono::after { content: "▾"; font-size: 1rem; transition: transform 0.15s; }
.fold[open] summary .mono::after { transform: rotate(180deg); }
.fold[open] summary { border-bottom: 1px dashed var(--rule); margin-bottom: 8px; }
.fold section { padding-top: 8px; }
.fold section .sh h2 { display: none; }
/* In this issue */
.index { display: grid; grid-template-columns: repeat(auto-fill, minmax(160px, 1fr)); gap: 8px; padding-block: 8px 4px; }
.index a { display: grid; gap: 4px; align-content: start; text-decoration: none; background: var(--surface); border: 1px solid var(--rule); padding: 10px 12px; min-height: 64px; }
.index a:hover { border-color: var(--ink-2); }
.index a .mono { color: var(--pylon-ink); }
.index a b { font-weight: 600; line-height: 1.3; font-size: 0.95rem; }
.index a { position: relative; padding-right: 30px; }
.index a::after { content: "→"; position: absolute; right: 12px; bottom: 10px; color: var(--ink-2); font-weight: 700; }
.index a:hover::after, .index a:focus-visible::after { color: var(--pylon-ink); }
.indexhd { display: flex; align-items: baseline; justify-content: space-between; gap: 12px; margin-top: 18px; }
.indexhd h2 { font-family: var(--display); font-weight: 900; text-transform: uppercase; font-size: 1.3rem; margin: 0; }
.indexhd span { color: var(--ink-2); font-size: 0.85rem; }

/* Sections */
section { padding-block: 44px 8px; }
.sh { display: flex; align-items: baseline; gap: 6px 14px; margin-bottom: 18px; flex-wrap: wrap; }
h2 { font-family: var(--display); font-weight: 800; font-stretch: 70%; text-transform: uppercase; font-size: clamp(1.9rem, 4.5vw, 2.6rem); line-height: 1; margin: 0; letter-spacing: 0.005em; }
.sh .mono { color: var(--ink-2); }
.col { max-width: 680px; }
.note { color: var(--ink-2); font-size: 0.88rem; margin-top: 12px; }

/* Score bugs */
.bugs { display: grid; grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); gap: 10px; }
.bug { background: var(--surface); border: 1px solid var(--rule); display: grid; grid-template-rows: auto 1fr auto; min-width: 0; }
.bug .top { display: flex; justify-content: space-between; align-items: center; padding: 7px 10px; border-bottom: 1px solid var(--rule); color: var(--ink-2); }
.bug .tag { color: var(--ink); }
.bug.hot .top { background: var(--pylon); color: var(--on-pylon); border-color: var(--pylon); }
.bug.hot .tag { color: var(--on-pylon); font-weight: 700; }
.bug .rows { padding: 6px 10px 2px; display: grid; }
.bug .ln { display: grid; grid-template-columns: auto minmax(0, 1fr) auto; align-items: center; gap: 2px 8px; padding-block: 5px; }
.bug .tm { font-weight: 600; font-size: 0.88rem; line-height: 1.2; min-width: 0; overflow-wrap: break-word; }
.bug .tm small { display: block; font-family: var(--mono); font-size: 0.64rem; font-weight: 400; color: var(--ink-2); letter-spacing: 0.04em; }
.bug .pts { font-family: var(--display); font-weight: 800; font-stretch: 80%; font-size: 1.6rem; line-height: 1; }
.bug .ln.lose .tm, .bug .ln.lose .pts { color: var(--ink-2); font-weight: 500; }
.bug .ln.lose .tb { opacity: 0.55; }
.split { height: 4px; display: flex; margin: 6px 10px 0; background: var(--bar-loss); }
.split i { display: block; width: var(--a); background: var(--win); }
.bug .bot { padding: 8px 10px 9px; color: var(--ink-2); }

/* Lead + telestrator */
.lead { display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); gap: 24px 48px; align-items: start; }
.lead .story p { font-size: 1.06rem; }
.tele { background: var(--surface); border: 1px solid var(--rule); padding: 16px; min-width: 0; }
.tele .head { display: grid; grid-template-columns: minmax(0, 1fr) 54px minmax(0, 1fr); gap: 8px; color: var(--ink-2); padding-bottom: 8px; border-bottom: 1px solid var(--rule); }
.tele .head span:last-child { text-align: right; }
.swap { display: grid; grid-template-columns: minmax(0, 1fr) 54px minmax(0, 1fr); gap: 8px; align-items: center; padding-block: 10px; border-bottom: 1px solid var(--rule); }
.swap .p { min-width: 0; display: flex; gap: 8px; align-items: center; }
.swap .p .sil { width: 30px; height: 30px; } .swap .p .sil svg { width: 24px; height: 24px; margin-top: 5px; }
.swap .p div { min-width: 0; }
.swap .p b { display: block; font-weight: 600; line-height: 1.25; overflow-wrap: break-word; }
.swap .p span.pos { font-family: var(--mono); font-size: 0.68rem; color: var(--ink-2); }
.swap .out b { color: var(--ink-2); text-decoration: line-through; text-decoration-color: var(--loss); text-decoration-thickness: 2px; }
.swap .in { flex-direction: row-reverse; text-align: right; }
.swap .arrow { display: grid; justify-items: center; gap: 2px; }
.swap .arrow svg { width: 44px; height: 14px; overflow: visible; }
.swap .arrow path { fill: none; stroke: var(--firstdown); stroke-width: 2.5; stroke-linecap: round; stroke-linejoin: round; }
.swap .arrow em { font-style: normal; font-family: var(--mono); font-size: 0.7rem; font-weight: 600; color: var(--win); }
.tele .sum { display: flex; justify-content: space-between; align-items: baseline; padding-top: 12px; gap: 12px; flex-wrap: wrap; }
.tele .sum .big { font-family: var(--display); font-weight: 900; font-stretch: 75%; font-size: 2.2rem; line-height: 1; color: var(--firstdown); }
@media (max-width: 860px) { .lead { grid-template-columns: 1fr; } }
@media (max-width: 480px) { .swap .p .sil { display: none; } }

/* Awards bento */
.bento { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 10px; }
.tile { background: var(--surface); border: 1px solid var(--rule); padding: 16px 16px 14px; display: flex; flex-direction: column; gap: 8px; min-width: 0; }
.tile.xl { grid-column: span 2; grid-row: span 2; background: var(--surface-2); }
.badge { align-self: flex-start; font-family: var(--mono); font-size: 0.66rem; font-weight: 600; letter-spacing: 0.06em; text-transform: uppercase; padding: 4px 9px; border-radius: 999px; border: 1.5px solid currentColor; color: var(--pylon-ink); transform: rotate(-2.5deg); }
.tile .tm { font-weight: 600; line-height: 1.25; overflow-wrap: break-word; display: flex; gap: 8px; align-items: center; }
.tile .stat { font-family: var(--display); font-weight: 900; font-stretch: 75%; font-size: 2.7rem; line-height: 0.95; }
.tile .stat small { font-family: var(--mono); font-size: 0.7rem; font-weight: 500; color: var(--ink-2); margin-left: 6px; letter-spacing: 0.04em; font-stretch: 90%; }
.tile.xl .stat { font-size: clamp(4rem, 9vw, 6.5rem); }
.tile p { margin: 0; font-size: 0.95rem; }
.tile.xl p { font-size: 1.05rem; max-width: 30em; }
.chipsrow { display: flex; gap: 8px; flex-wrap: wrap; margin-top: auto; }
.chipsrow span { background: var(--bg); border: 1px solid var(--rule); padding: 4px 9px; }
@media (max-width: 900px) { .bento { grid-template-columns: repeat(2, minmax(0, 1fr)); } .tile.xl { grid-row: auto; } }
@media (max-width: 540px) { .bento { grid-template-columns: 1fr; } .tile.xl { grid-column: auto; } }

/* Standings */
.tablebox { overflow-x: auto; border: 1px solid var(--rule); background: var(--surface); }
.stand { width: 100%; border-collapse: collapse; min-width: 700px; font-variant-numeric: tabular-nums; }
.stand th, .stand td { padding: 10px 12px; text-align: right; border-bottom: 1px solid var(--rule); white-space: nowrap; }
.stand th { font-family: var(--mono); font-size: 0.66rem; font-weight: 500; letter-spacing: 0.06em; text-transform: uppercase; color: var(--ink-2); }
.stand th.l, .stand td.l { text-align: left; }
.stand td.seed { font-family: var(--display); font-weight: 900; font-stretch: 75%; font-size: 1.3rem; text-align: left; width: 44px; }
.stand td.team { text-align: left; white-space: normal; min-width: 210px; }
.stand td.team div { display: flex; gap: 10px; align-items: center; font-weight: 600; line-height: 1.25; }
.stand td.team .mode { margin-top: 3px; color: var(--ink-2); }
.pf { display: grid; grid-template-columns: 76px 90px; gap: 10px; align-items: center; justify-content: end; }
