@media (max-width: 760px) { .docket .grid2 { grid-template-columns: 1fr; } }
@media (max-width: 560px) { .mu .vs { grid-template-columns: 1fr; gap: 8px; } .side2.r { justify-items: start; text-align: left; } .side2.r .nm { flex-direction: row; } .mu .v { padding: 0; font-size: 1rem; } }

/* Chopping block */
.map { position: relative; background: var(--surface); border: 1px solid var(--rule); height: 380px; margin-bottom: 10px; overflow: hidden; }
