.map .q { position: absolute; font-family: var(--mono); font-size: 0.62rem; letter-spacing: 0.06em; text-transform: uppercase; color: var(--ink-2); }
.map .ax { position: absolute; font-family: var(--mono); font-size: 0.62rem; letter-spacing: 0.06em; text-transform: uppercase; color: var(--ink-2); }
.dot { position: absolute; left: var(--x); top: var(--y); transform: translate(-50%, -50%); display: flex; align-items: center; gap: 5px; }
.dot i { width: 12px; height: 12px; border-radius: 50%; background: var(--mc); outline: 2px solid var(--surface); }
.dot span { font-family: var(--display); font-weight: 800; font-stretch: 85%; font-size: 0.8rem; color: var(--ink); white-space: nowrap; }
