.axe .who { display: flex; gap: 12px; align-items: center; margin: 12px 0 10px; }
.axe .who b { font-family: var(--display); font-weight: 900; font-stretch: 70%; text-transform: uppercase; font-size: clamp(1.7rem, 4vw, 2.4rem); line-height: 0.92; overflow-wrap: break-word; }
.axe ul { list-style: none; padding: 0; margin: 14px 0 0; display: grid; gap: 0; border-top: 1px solid var(--rule); }
.axe li { display: grid; grid-template-columns: 130px minmax(0, 1fr); gap: 4px 12px; padding-block: 8px; border-bottom: 1px solid var(--rule); }
.axe li span:first-child { color: var(--ink-2); }
.stack { display: grid; gap: 10px; align-content: start; }
.mini-card { background: var(--surface); border: 1px solid var(--rule); padding: 14px 16px; min-width: 0; }
