@media (max-width: 860px) { .block { grid-template-columns: 1fr; } }
@media (max-width: 520px) { .map { height: 340px; } .axe li { grid-template-columns: 1fr; } }

/* Every team chart */
.wk { border-top: 1px solid var(--rule); }
.wk-row { display: grid; grid-template-columns: minmax(0, 250px) minmax(0, 1fr) 132px; gap: 4px 16px; align-items: center; padding-block: 9px; border-bottom: 1px solid var(--rule); }
