.wl { flex: none; width: 20px; height: 20px; display: grid; place-items: center; font-family: var(--mono); font-size: 0.66rem; font-weight: 700; color: var(--bg); }
.wl.W { background: var(--win); } .wl.L { background: var(--loss); }
