/* Trade */
.trade { display: grid; grid-template-columns: minmax(0, 1fr) auto minmax(0, 1fr); gap: 10px; align-items: stretch; }
.side { background: var(--surface); border: 1px solid var(--rule); padding: 16px; min-width: 0; }
