.card p { margin: 0; font-size: 0.93rem; }
.trend { align-self: flex-start; font-family: var(--mono); font-size: 0.66rem; font-weight: 600; padding: 3px 8px; background: var(--surface-2); color: var(--win); }



/* Risers and fallers */
