.mv { background: var(--surface); border: 1px solid var(--rule); padding: 14px 16px; min-width: 0; display: grid; gap: 10px; align-content: start; }
.mv .hd { display: flex; gap: 10px; align-items: center; flex-wrap: wrap; font-weight: 700; line-height: 1.2; }
.mv .hd .mode { margin-left: auto; }
.mvrow { display: grid; grid-template-columns: 76px minmax(0, 1fr); gap: 4px 12px; padding-top: 10px; border-top: 1px solid var(--rule); }
.delta { align-self: start; display: grid; gap: 2px; justify-items: start; }
.delta b { font-family: var(--display); font-weight: 900; font-stretch: 80%; font-size: 1.25rem; line-height: 1; }
.delta.up b { color: var(--win); } .delta.dn b { color: var(--loss); }
.delta span { font-family: var(--mono); font-size: 0.58rem; letter-spacing: 0.06em; text-transform: uppercase; color: var(--ink-2); }
.mvp { min-width: 0; }
