@media (max-width: 760px) { .movers { grid-template-columns: 1fr; } }

/* Contributor pages */
.contrib { display: inline-flex; align-items: center; gap: 8px; color: var(--ink-2); }
.notif { display: grid; grid-template-columns: 44px minmax(0, 1fr); gap: 4px 12px; align-items: start; max-width: 520px; background: var(--surface-2); border: 1px solid var(--rule); border-radius: 18px; padding: 12px 14px; margin-bottom: 18px; }
.notif .ic { width: 44px; height: 44px; border-radius: 11px; background: var(--pylon); color: var(--on-pylon); display: grid; place-items: center; font-family: var(--display); font-weight: 900; font-style: italic; font-stretch: 80%; font-size: 0.95rem; grid-row: span 2; }
.notif .top { display: flex; justify-content: space-between; gap: 8px; color: var(--ink-2); }
.notif .msg b { display: block; font-weight: 700; }
.byline { display: flex; flex-wrap: wrap; gap: 8px 18px; align-items: center; margin-bottom: 14px; color: var(--ink-2); }
.byline .who { display: flex; gap: 8px; align-items: center; color: var(--ink); font-weight: 600; }
.tiers { border: 1px solid var(--rule); background: var(--surface); }
.tier { display: grid; grid-template-columns: 190px minmax(0, 1fr); border-bottom: 1px solid var(--rule); }
