.nfl { display: inline-flex; align-items: center; gap: 6px; background: var(--bg); border: 1px solid var(--rule); padding: 5px 9px 5px 6px; font-weight: 600; font-size: 0.9rem; line-height: 1; }
.nfl .mv { font-family: var(--mono); font-size: 0.68rem; font-weight: 700; padding: 2px 5px; border-radius: 4px; margin-left: 4px; align-self: center; }
