.ednote { margin-top: 10px; color: var(--ink-2); font-size: 0.88rem; }
.ednote b { color: var(--firstdown); font-weight: 600; }
@media (max-width: 600px) { .tier { grid-template-columns: 1fr; } .tier .lab { flex-direction: row; align-items: baseline; flex-wrap: wrap; gap: 4px 10px; } }

.room { display: grid; grid-template-columns: 260px minmax(0, 1fr); border: 1px solid var(--rule); background: var(--surface); }
