.host .nm { display: flex; gap: 10px; align-items: center; }
.host .nm b { font-family: var(--display); font-weight: 900; font-stretch: 72%; text-transform: uppercase; font-size: 1.6rem; line-height: 0.95; }
.host dl { margin: 0; display: grid; grid-template-columns: auto 1fr; gap: 6px 12px; font-size: 0.9rem; }
