@media (max-width: 760px) { .room { grid-template-columns: 1fr; } .room .host { border-right: 0; border-bottom: 1px solid var(--rule); } .room .page { padding: 18px 16px; } }

/* v3: lean issue. Lead swaps live in the hero, contributors near the top, week ahead + chopping block in one section */
.hero-row.has-tele { grid-template-areas: "deck race" "tele race"; }
