.wk8 .grid3 { display: grid; grid-template-columns: repeat(auto-fit, minmax(min(100%, 300px), 1fr)); gap: 10px; }
.wk8 .axe { border-top-width: 6px; }
.wk8 .grid3 .mu .vs { grid-template-columns: 1fr; gap: 6px; }
.wk8 .grid3 .side2.r { justify-items: start; text-align: left; }
