@media (min-width: 900px) { .bugs.feat { grid-template-columns: repeat(3, minmax(0, 1fr)); } .bugs.feat .bug.hot { grid-column: span 2; } .bugs.feat .bug.hot .pts { font-size: 2.2rem; } .bugs.feat .bug.hot .tm { font-size: 1rem; } }
.axe .vsline { display: flex; flex-wrap: wrap; gap: 6px 10px; align-items: center; margin-top: 4px; color: var(--ink-2); }
