.axe .twocol { display: grid; grid-template-columns: minmax(0, 1.1fr) minmax(0, 1fr); gap: 4px 28px; align-items: start; }
@media (max-width: 860px) { .axe .twocol { grid-template-columns: 1fr; } }
.subh { margin: 26px 0 12px; color: var(--ink-2); display: flex; align-items: center; gap: 10px; }
.subh::after { content: ""; flex: 1; height: 1px; background: var(--rule); }

/* Tip line: anonymous drama box + approved tips as headlines */
.chips a[href="#tipbox"] { background: var(--firstdown); color: var(--on-firstdown); border-color: var(--firstdown); }
.spill { display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1.25fr); gap: 20px 44px; background: var(--surface); border: 1px solid var(--rule); border-top: 6px solid var(--firstdown); padding: 24px; position: relative; }
.spill .pitch p { font-size: 1.05rem; }
.spill .pitch .big { font-family: var(--quote, var(--display)); font-style: italic; font-size: clamp(1.6rem, 4.4vw, 2.3rem); line-height: 1.1; color: var(--firstdown); margin-bottom: 14px; }
.spill .fine { color: var(--ink-2); font-size: 0.88rem; }
.spill form { display: grid; gap: 14px; align-content: start; min-width: 0; }
.spill label { display: grid; gap: 6px; }
.spill label > span { font-family: var(--mono); font-size: 0.7rem; font-weight: 600; letter-spacing: 0.08em; text-transform: uppercase; color: var(--ink-2); display: flex; justify-content: space-between; gap: 8px; }
.spill textarea, .spill input[type=text] { width: 100%; background: var(--bg); color: var(--ink); border: 1px solid var(--rule); padding: 12px 14px; font-family: var(--body); font-size: 16px; line-height: 1.5; border-radius: 0; }
.spill textarea { min-height: 150px; resize: vertical; }
.spill textarea:focus, .spill input[type=text]:focus { outline: 3px solid var(--firstdown); outline-offset: 0; border-color: var(--firstdown); }
.spill .go { display: flex; gap: 12px 16px; align-items: end; flex-wrap: wrap; }
.spill .go label { flex: 1 1 200px; }
.spill button { flex: none; background: var(--firstdown); color: var(--on-firstdown); border: 0; padding: 13px 20px 12px; font-family: var(--display); font-weight: 900; text-transform: uppercase; font-size: 1.15rem; letter-spacing: 0.02em; cursor: pointer; clip-path: polygon(0 0, 100% 0, 100% 72%, 92% 100%, 0 100%); }
.spill button:focus-visible { outline: 3px solid var(--ink); outline-offset: 3px; }
.spill button[disabled] { opacity: 0.6; cursor: wait; }
.spill .msg { min-height: 1.5em; margin: 0; font-weight: 600; }
.spill .msg.ok { color: var(--win); } .spill .msg.err { color: var(--loss); }
.spill .hp { position: absolute; left: -9999px; width: 1px; height: 1px; overflow: hidden; }
@media (max-width: 760px) { .spill { grid-template-columns: 1fr; padding: 18px 16px; } }
.tips { display: grid; gap: 10px; }
.tipcard { background: var(--surface); border: 1px solid var(--rule); padding: 18px 20px 20px; }
.tipcard .fire { display: inline-flex; align-items: center; gap: 6px; margin-top: 12px; min-height: 40px; padding: 4px 14px; border: 2px solid var(--rule); border-radius: 999px; background: var(--bg); color: var(--ink); font: inherit; font-weight: 700; cursor: pointer; }
.tipcard .fire[aria-pressed="true"] { border-color: var(--pylon); background: color-mix(in srgb, var(--pylon) 14%, transparent); }
.tipcard .fire b { font-variant-numeric: tabular-nums; }
.tipcard .stamp.choice { border-color: var(--firstdown); color: var(--firstdown); margin-left: 8px; transform: rotate(1.5deg); }
.tipcard .stamp { display: inline-block; border: 2px solid var(--loss); color: var(--loss); font-family: var(--mono); font-weight: 700; font-size: 0.72rem; letter-spacing: 0.1em; text-transform: uppercase; padding: 3px 8px; transform: rotate(-2deg); }
.tipcard h3 { font-family: var(--display); font-weight: 900; text-transform: uppercase; font-size: clamp(1.8rem, 4.6vw, 2.8rem); line-height: 1; margin: 12px 0 12px; text-wrap: balance; }
.tipcard blockquote { margin: 0; font-family: var(--quote, var(--body)); font-style: italic; font-size: 1.15rem; line-height: 1.45; color: var(--ink-2); border-left: 3px solid var(--firstdown); padding-left: 12px; max-width: 46em; }

/* Desk-filled sections: real columns, editor's note, BBO history, roasts */
.prose { font-size: 1.06rem; line-height: 1.6; max-width: 62ch; }
.prose p { margin: 0 0 14px; } .prose ul, .prose ol { margin: 0 0 14px; padding-left: 1.3em; } .prose li { margin-bottom: 4px; }
.prose a { color: var(--pylon-ink); text-underline-offset: 2px; }
.prose blockquote.pq, .pq { margin: 18px 0; padding: 4px 0 4px 16px; border-left: 5px solid var(--pylon); font-family: var(--quote, var(--display)); font-style: italic; font-size: clamp(1.35rem, 3.4vw, 1.8rem); line-height: 1.2; color: var(--ink); }
.colhead { font-family: var(--display); font-weight: 900; text-transform: uppercase; font-size: clamp(1.9rem, 5vw, 2.9rem); line-height: 0.98; margin: 0 0 14px; text-wrap: balance; }
.pieceimg { margin: 16px 0; } .pieceimg img { display: block; max-width: 100%; max-height: 520px; border: 1px solid var(--rule); }
.room .page .prose { max-width: none; }
.roast { background: var(--surface); border: 1px dashed var(--ink-2); padding: 22px 24px; display: grid; gap: 8px; max-width: 680px; }
.roast .mono { color: var(--loss); } .roast p { margin: 0; font-size: 1.15rem; font-family: var(--quote, var(--body)); font-style: italic; }
.ednote-box { display: grid; grid-template-columns: auto minmax(0, 1fr); gap: 14px 18px; align-items: start; background: var(--surface); border: 1px solid var(--rule); border-left: 6px solid var(--pylon); padding: 20px 22px; }
.ednote-box .tb.lg { margin-top: 4px; }
.ednote-box .colhead { font-size: clamp(1.5rem, 4vw, 2.2rem); margin-bottom: 8px; }
.ednote-box .prose { font-size: 1.02rem; } .ednote-box .prose p:last-child { margin-bottom: 0; }
@media (max-width: 560px) { .ednote-box { grid-template-columns: 1fr; } }
.hist { display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1.2fr); gap: 20px 40px; align-items: start; }
.histcard { background: var(--surface-2); border: 1px solid var(--rule); padding: 16px 18px; min-width: 0; }
.histcard .yr { font-family: var(--display); font-weight: 900; font-size: clamp(2.6rem, 7vw, 3.6rem); line-height: 0.9; color: var(--firstdown); }
.histcard .wk { color: var(--ink-2); margin: 2px 0 12px; }
.histgame { display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 2px 12px; padding: 8px 0; border-top: 1px solid var(--rule); font-size: 0.95rem; }
.histgame .l { color: var(--ink-2); } .histgame .pts { font-variant-numeric: tabular-nums; font-weight: 700; text-align: right; } .histgame .l .pts { font-weight: 500; }
.histgame.high .w { color: var(--firstdown); }
.histcard .foot { margin-top: 10px; color: var(--ink-2); }
.histgame small { font-size: 0.72rem; margin-left: 4px; }
.histnums { margin-top: 12px; border-top: 1px solid var(--rule); display: grid; }
.histnums div { display: grid; grid-template-columns: 90px minmax(0, 1fr); gap: 10px; padding: 6px 0; border-bottom: 1px solid var(--rule); font-size: 0.9rem; }
.histnums .mono { color: var(--ink-2); padding-top: 2px; }
.histtop { margin: 6px 0 0; padding: 0; list-style: none; counter-reset: tp; font-size: 0.92rem; } .histtop li { display: grid; grid-template-columns: 22px minmax(0, 1fr) auto; gap: 0 8px; padding: 5px 0; border-bottom: 1px solid var(--rule); align-items: baseline; } .histtop li::before { counter-increment: tp; content: counter(tp); font-family: var(--mono); color: var(--ink-2); grid-row: 1 / span 2; } .histtop li b { font-weight: 600; grid-column: 2; } .histtop li .dim { grid-column: 2; font-size: 0.8rem; } .histtop li .pts { grid-column: 3; grid-row: 1 / span 2; align-self: center; font-weight: 700; font-variant-numeric: tabular-nums; }
@media (max-width: 860px) { .hist { grid-template-columns: 1fr; } }

footer { margin-top: 52px; border-top: 1px solid var(--rule); padding-top: 18px; color: var(--ink-2); font-size: 0.88rem; }
footer .row { display: flex; gap: 12px 32px; flex-wrap: wrap; justify-content: space-between; align-items: start; }
footer p { max-width: 62ch; margin: 0; }
footer .credit { text-align: right; display: grid; gap: 4px; }
footer .credit b { color: var(--ink); font-family: var(--display); font-weight: 800; font-stretch: 80%; font-size: 1.1rem; letter-spacing: 0.02em; text-transform: uppercase; }
@media (max-width: 640px) { footer .credit { text-align: left; } }

@media (prefers-reduced-motion: reduce) { html { scroll-behavior: auto; } .ring path { animation: none; } }
:root { --display: "Big Shoulders Display", "Arial Narrow", sans-serif; --body: "Barlow", system-ui, -apple-system, "Segoe UI", sans-serif; --mono: "Barlow Condensed", "Arial Narrow", sans-serif; --script: "Yellowtail", cursive; --quote: "Newsreader", Georgia, serif; }

h1 { font-style: normal; font-size: clamp(4rem, 15vw, 9.5rem); line-height: 1.04; letter-spacing: 0; }
h2 { font-size: clamp(2.3rem, 5.6vw, 3.2rem); letter-spacing: 0.01em; }
.brand .mark { font-style: normal; font-size: 1.15rem; }
.brand .word { font-size: 1.6rem; letter-spacing: 0.02em; }
.mono, .mode, .sticker, .hh, .onair, .tier .lab small, .nfl b, .stand th, .totop { font-size: 0.86rem; letter-spacing: 0.07em; }
.mono { font-weight: 600; }
.tier .lab { font-size: 1.6rem; }
.rk-quote { font-size: clamp(2.5rem, 8.2vw, 4.4rem); line-height: 1.05; transform: rotate(-2deg); transform-origin: left center; margin-bottom: 26px; }
.signoff { font-size: 2.2rem; }

.rk-quote, .signoff, .contrib { font-family: var(--script); font-weight: 400; font-style: normal; font-stretch: normal; text-transform: none; letter-spacing: 0; font-synthesis: none; }

.ring { margin-inline: 0.22em; }
.ring svg { left: -13%; width: 126%; top: -17%; height: 134%; }

.rk-quote, .pq { font-family: var(--quote); font-style: italic; font-weight: 500; font-stretch: normal; text-transform: none; letter-spacing: -0.01em; font-synthesis: none; }
.rk-quote { font-size: clamp(2.2rem, 7.4vw, 4.1rem); line-height: 1.04; transform: none; margin-bottom: 22px; }
/* Barlow Condensed runs small; lift the tiny label sizes that were set for Martian Mono */
.swap .p span.pos, .swap .arrow em, .bug .tm small, .side2 .rec, .host dt, .mvp a, .trend, .tile .stat small, .wk-val span, .pip, .wl, .vbar, .mvrow .delta span, .slot > span, .chipsrow span { font-size: 0.8rem; letter-spacing: 0.04em; }

/* Issue drawer */
.menu-btn { order: -1; width: 40px; height: 40px; display: grid; place-content: center; gap: 5px; background: var(--surface); border: 1px solid var(--rule); border-radius: 10px; cursor: pointer; padding: 0; }
.menu-btn i { display: block; width: 18px; height: 2px; background: var(--ink); border-radius: 2px; }
.menu-btn:focus-visible { outline: 3px solid var(--firstdown); outline-offset: 2px; }
.drawer-bg { position: fixed; inset: 0; background: rgba(5, 10, 20, 0.6); z-index: 40; }
.drawer { position: fixed; top: 0; bottom: 0; left: 0; width: min(320px, 86vw); background: var(--surface); border-right: 1px solid var(--rule); z-index: 41; padding: calc(16px + env(safe-area-inset-top, 0px)) 18px 24px; overflow-y: auto; box-shadow: 12px 0 40px rgba(0,0,0,0.35); animation: drawerin 0.18s ease-out; }
@keyframes drawerin { from { transform: translateX(-24px); opacity: 0; } to { transform: none; opacity: 1; } }
.drawer .dh { display: flex; justify-content: space-between; align-items: center; margin-bottom: 18px; }
.drawer .dclose { width: 40px; height: 40px; border: 1px solid var(--rule); background: var(--bg); color: var(--ink); border-radius: 10px; font-size: 1rem; cursor: pointer; }
.drawer .issues { list-style: none; margin: 8px 0 0; padding: 0; display: grid; gap: 8px; }
.drawer .issues a { display: grid; gap: 2px; text-decoration: none; background: var(--bg); border: 1px solid var(--rule); padding: 10px 14px; position: relative; min-height: 56px; }
.drawer .issues a .mono { color: var(--pylon-ink); }
.drawer .issues a b { font-family: var(--display); font-weight: 800; font-size: 1.25rem; line-height: 1; text-transform: uppercase; }
.drawer .issues a em { position: absolute; right: 12px; top: 12px; font-style: normal; font-family: var(--mono); font-size: 0.66rem; letter-spacing: 0.08em; text-transform: uppercase; background: var(--firstdown); color: var(--on-firstdown); padding: 3px 7px; }
.drawer .issues a[aria-current="page"] { border-color: var(--firstdown); }
.drawer .issues a:hover { border-color: var(--ink-2); }
@media (prefers-reduced-motion: reduce) { .drawer { animation: none; } }

/* Brain logo mark */
.brand .mark.logo { display: grid; place-items: center; padding: 3px 6px 2px; height: 34px; width: 46px; box-sizing: border-box; }
.brand .mark.logo svg { width: 36px; height: 27px; display: block; }
:root[data-theme="light"] .brand .mark.logo svg path[fill="#0A1220"] { fill: #FFFFFF; }
:root[data-theme="light"] .brand .mark.logo svg path[stroke="#FF6A1F"] { stroke: #E85A12; }
:root[data-theme="light"] .brand .mark.logo svg path[stroke="#FFD60A"] { stroke: #141B29; }

/* Full-width masthead (scrolls away; the score bar below it sticks) */
.masthead { background: var(--bg); border-bottom: 1px solid var(--rule); }
.masthead .wrap { display: flex; flex-direction: column; align-items: center; text-align: center; gap: 6px; padding: 22px 0 16px; }
.masthead .kick { font-family: var(--quote); font-style: italic; font-weight: 500; font-size: clamp(1.1rem, 3.4vw, 1.5rem); color: var(--firstdown); line-height: 1; }
.masthead .mrule { display: flex; align-items: center; gap: 14px; width: 100%; margin: 4px 0 2px; }
.masthead .mrule i { flex: 1; height: 4px; background: var(--firstdown); display: block; }
.masthead .mbrain { display: block; width: clamp(56px, 12vw, 84px); flex: none; }
.masthead .mbrain svg { width: 100%; height: auto; display: block; }
.masthead .mbrain svg path[fill="#0A1220"] { fill: var(--pylon); }
.masthead .mbrain svg path[stroke="#FF6A1F"] { stroke: var(--bg); }
.masthead .mtitle { font-family: var(--display); font-weight: 900; font-style: normal; text-transform: uppercase; font-size: clamp(2.6rem, 10.2vw, 5.6rem); line-height: 0.9; letter-spacing: 0.01em; margin: 0; white-space: nowrap; }
.masthead .mdate { display: flex; flex-wrap: wrap; justify-content: center; gap: 6px 10px; color: var(--ink-2); margin-top: 4px; }
.masthead .mdate b { color: var(--pylon-ink); }
:root[data-theme="light"] .masthead .mrule i { background: var(--ink); }
:root[data-theme="light"] .masthead .mbrain svg path[fill="#0A1220"] { fill: #E85A12; }
:root[data-theme="light"] .masthead .mbrain svg path[stroke="#FFD60A"] { stroke: #141B29; }
@media (max-width: 420px) { .masthead .mtitle { font-size: 2.5rem; } }
.bar .brand .word { display: none; }
.bar .brand .btag { color: var(--ink-2); font-size: 0.72rem; letter-spacing: 0.08em; white-space: nowrap; }
.drawer .issues a em.here { background: var(--surface-2); color: var(--ink-2); }
/* Small logo in the sticky bar, only once the masthead has scrolled away */
.bar .brand { display: flex; opacity: 0; transform: translateY(-6px); transition: opacity 0.18s, transform 0.18s; pointer-events: none; }
.bar.scrolled .brand { opacity: 1; transform: none; pointer-events: auto; }
.masthead .mdate + .mdate { margin-top: 2px; color: var(--ink); }
.masthead .mdate + .mdate b { color: var(--ink-2); font-weight: 500; }

.masthead .wrap { gap: 2px; padding: 14px 0 12px; }
.masthead .mrule { margin: 0 0 2px; }
.masthead .mbrain { width: clamp(48px, 10vw, 64px); }
.masthead .mtitle { line-height: 0.88; }
.masthead .mdate { margin-top: 2px; font-size: 0.78rem; }
.bar .wrap { padding-block: 8px 6px; }
.bar .theme-toggle { margin-left: auto; }

/* Comment photos */
.cmts .rowr { display: flex; gap: 8px; align-items: center; }
.cmts .photo { width: 44px; height: 44px; display: grid; place-items: center; background: var(--bg); border: 1px solid var(--rule); border-radius: 10px; color: var(--ink); cursor: pointer; padding: 0; }
.cmts .photo svg { width: 22px; height: 22px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linejoin: round; }
.cmts .photo:disabled { opacity: 0.4; cursor: not-allowed; }
.cmts .pv { position: relative; width: fit-content; margin: 8px 0 2px; }
.cmts .pv img { display: block; max-width: 160px; max-height: 160px; border: 1px solid var(--rule); }
.cmts .pv .rm { position: absolute; top: -8px; right: -8px; width: 26px; height: 26px; border-radius: 50%; border: 0; background: var(--ink); color: var(--bg); font-size: 0.8rem; cursor: pointer; }
.cmts .c .cimg { grid-column: 2; display: block; margin-top: 6px; width: fit-content; max-width: 100%; }
.cmts .c .cimg img { display: block; max-width: min(100%, 420px); max-height: 420px; border: 1px solid var(--rule); }

/* Comment reactions */
.cmts .c .react { grid-column: 2; display: flex; gap: 8px; margin-top: 6px; }
.cmts .c .react button { display: inline-flex; align-items: center; gap: 6px; min-height: 34px; padding: 4px 12px; border-radius: 999px; border: 1px solid var(--rule); background: var(--bg); color: var(--ink-2); font: inherit; font-size: 0.85rem; cursor: pointer; }
.cmts .c .react button span { font-size: 1rem; line-height: 1; }
.cmts .c .react button b { font-weight: 700; font-family: var(--mono); }
.cmts .c .react button[aria-pressed="true"] { border-color: var(--firstdown); background: color-mix(in srgb, var(--firstdown) 18%, var(--bg)); color: var(--ink); }
.cmts .c .react button:disabled { opacity: 0.6; }

/* Replies */
.cmts .c .react .rp { margin-left: auto; }
.cmts .replies { margin: 6px 0 10px 24px; padding-left: 14px; border-left: 2px solid var(--rule); display: grid; gap: 10px; }
.cmts .replies .c { padding: 0; border: 0; }
.cmts .replyto { display: flex; justify-content: space-between; align-items: center; gap: 10px; margin-bottom: 8px; padding: 8px 12px; background: var(--surface-2); border-left: 3px solid var(--firstdown); color: var(--ink-2); }
.cmts .replyto b { color: var(--ink); }
.cmts .replyto button { width: 28px; height: 28px; border: 0; border-radius: 50%; background: var(--bg); color: var(--ink); cursor: pointer; }

/* Reactions v2: pills only when used; smiley opens the picker; long-press a pill for names */
.cmts .c .react { align-items: center; flex-wrap: wrap; }
.cmts .c .react .addr { position: relative; display: inline-flex; }
.cmts .c .react .add { width: 34px; height: 34px; padding: 0; border-radius: 50%; display: grid; place-items: center; }
.cmts .c .react .add svg { width: 18px; height: 18px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; }
.cmts .c .react .add[aria-expanded="true"] { border-color: var(--ink-2); color: var(--ink); }
.cmts .c .react .menu { position: absolute; left: 0; bottom: calc(100% + 6px); display: flex; gap: 4px; padding: 4px; background: var(--surface); border: 1px solid var(--rule); border-radius: 999px; box-shadow: 0 8px 24px rgba(0,0,0,0.35); z-index: 5; }
.cmts .c .react .menu button { width: 40px; height: 40px; padding: 0; border-radius: 50%; font-size: 1.2rem; }
.cmts .c .react .menu button[aria-pressed="true"] { border-color: var(--firstdown); background: color-mix(in srgb, var(--firstdown) 18%, var(--bg)); }
.cmts .c .whor { grid-column: 2; display: flex; flex-wrap: wrap; gap: 4px 14px; color: var(--ink-2); font-size: 0.72rem; margin-top: 4px; }
.cmts .c .whor i { font-style: normal; margin-right: 4px; }

/* Week 9: deadline lead */
.mast-art { margin: 0 0 14px; }
.phone-art { width: min(320px, 100%); height: auto; display: block; overflow: visible; }
.phone-art .handset path { fill: var(--pylon); transform-origin: 40px 46px; animation: ringwobble 1.6s ease-in-out infinite; }
.phone-art .rings path { fill: none; stroke: var(--firstdown); stroke-width: 4; stroke-linecap: round; opacity: 0; animation: ringpulse 1.6s ease-out infinite; }
.phone-art .rings .ring2 { animation-delay: 0.25s; }
.phone-art .fax rect:first-child { fill: var(--surface-2); stroke: var(--rule); }
.phone-art .fax rect:last-child { fill: var(--bg); }
.phone-art .slip rect { fill: var(--firstdown); }
.phone-art .slip text { font-family: var(--mono); font-weight: 700; font-size: 17px; letter-spacing: 0.08em; fill: var(--on-firstdown); }
.phone-art .slip circle { fill: var(--on-firstdown); }
.phone-art .slip { transform-origin: 118px 49px; animation: slipout 4.8s cubic-bezier(.2,.8,.2,1) infinite; }
@keyframes ringwobble { 0%,100% { transform: rotate(0deg); } 10% { transform: rotate(-14deg); } 20% { transform: rotate(12deg); } 30% { transform: rotate(-10deg); } 40% { transform: rotate(8deg); } 50% { transform: rotate(0deg); } }
@keyframes ringpulse { 0% { opacity: 0; transform: translateX(-6px); } 30% { opacity: 1; } 70% { opacity: 0; transform: translateX(8px); } 100% { opacity: 0; } }
@keyframes slipout { 0% { transform: scaleX(0); } 25% { transform: scaleX(1); } 85% { transform: scaleX(1); opacity: 1; } 95% { opacity: 0; } 100% { transform: scaleX(0); opacity: 0; } }
@media (prefers-reduced-motion: reduce) { .phone-art .handset path, .phone-art .slip { animation: none; } .phone-art .rings path { animation: none; opacity: 1; } }
.hero-row.solo { grid-template-columns: 1fr; }
.deals { display: grid; gap: 12px; }
.deal { background: var(--surface); border: 1px solid var(--rule); border-top: 4px solid var(--pylon); padding: 16px 18px 18px; min-width: 0; }
.dealhd { display: flex; justify-content: space-between; align-items: center; gap: 10px; flex-wrap: wrap; margin-bottom: 12px; }
.dealvs { display: grid; grid-template-columns: minmax(0, 1fr) auto minmax(0, 1fr); gap: 10px 14px; align-items: center; padding-bottom: 12px; border-bottom: 1px solid var(--rule); }
.dside { display: grid; gap: 4px; min-width: 0; }
.dside .mono { color: var(--ink-2); }
.dside b { font-family: var(--display); font-weight: 900; text-transform: uppercase; font-size: clamp(1.25rem, 3.4vw, 1.7rem); line-height: 1; overflow-wrap: break-word; }
.dside.r { text-align: right; justify-items: end; }
.takes p { margin: 10px 0 0; font-size: 0.98rem; }
.takes p b { color: var(--pylon-ink); font-weight: 600; }
@media (max-width: 560px) { .dealvs { grid-template-columns: 1fr; } .dealvs .swapicon svg { transform: rotate(90deg); } .dside.r { text-align: left; justify-items: start; } }
.ddt { min-width: 760px; }
.ddt th.l, .ddt td.l { text-align: left; }
.ddt td.why { white-space: normal; min-width: 280px; font-size: 0.9rem; line-height: 1.4; color: var(--ink-2); }
.ddt td.up { color: var(--win); font-weight: 700; } .ddt td.dn { color: var(--loss); font-weight: 700; }
.ddt tbody tr:nth-child(even) td, .stand tbody tr:nth-child(even) td { background: color-mix(in srgb, var(--surface-2) 45%, transparent); }
.ddt thead th, .stand thead th { position: sticky; top: 0; background: var(--surface); z-index: 1; }
/* Week 9 polish: steadier rhythm, rules under section heads, calmer chips */
.sh { padding-bottom: 10px; border-bottom: 1px solid var(--rule); }
.sh h2 { letter-spacing: 0.012em; }
.col p, .prose p { text-wrap: pretty; }
.cmchip:focus-visible, .chips a:focus-visible, .fire:focus-visible, .theme-toggle:focus-visible { outline: 3px solid var(--firstdown); outline-offset: 2px; }
.tile, .mv, .mu, .deal, .tipcard, .card { transition: border-color 0.15s; }
.tile:hover, .mv:hover, .mu:hover, .deal:hover, .tipcard:hover { border-color: var(--ink-2); }
.index a { transition: border-color 0.15s, transform 0.15s; } .index a:hover { transform: translateY(-1px); }
footer { padding-top: 22px; }

@media (max-width: 760px) {
  .ddbox { overflow: visible; border: 0; background: none; }
  .ddt { min-width: 0; display: block; }
  .ddt thead { display: none; }
  .ddt tbody { display: grid; gap: 10px; }
  .ddt tr { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 6px 10px; background: var(--surface); border: 1px solid var(--rule); padding: 12px 14px; }
  .ddt tbody tr:nth-child(even) td { background: none; }
  .ddt td { display: block; padding: 0; border: 0; white-space: normal; text-align: left; }
  .ddt td.pl, .ddt td.mvv, .ddt td.why { grid-column: 1 / -1; }
  .ddt td.mvv { color: var(--ink-2); font-size: 0.9rem; }
  .ddt td[data-l]:not(.mvv)::before { content: attr(data-l); display: block; font-family: var(--mono); font-size: 0.72rem; letter-spacing: 0.06em; text-transform: uppercase; color: var(--ink-2); margin-bottom: 2px; }
  .ddt td[data-l]:not(.mvv) { font-family: var(--display); font-weight: 800; font-size: 1.3rem; line-height: 1; padding-top: 4px; }
  .ddt td.why { min-width: 0; padding-top: 6px; border-top: 1px solid var(--rule); margin-top: 4px; }
}
#lead { padding-top: 24px; }

/* Week 9: highlighter instead of the ring */
h1 .hl { display: inline-block; background: var(--firstdown); color: var(--on-firstdown); padding: 0 0.14em 0.02em; margin: 0 0.04em; transform: rotate(-1.6deg); box-shadow: 0.08em 0.08em 0 0 var(--pylon); }
@media (max-width: 480px) { h1 .hl { transform: rotate(-1deg); } }

/* Deal cards on phones: arrow sits left, between the two sides */
@media (max-width: 560px) {
  .dealvs { gap: 6px; }
  .dealvs .swapicon { justify-items: start; padding: 2px 0 2px 4px; }
  .dealvs .swapicon svg { width: 28px; height: 28px; transform: rotate(90deg); }
}
/* Added by the publisher (appended to the Week 9 CSS by mktemplate.mjs). Headline effects + the BBArchive folder. */
h1 .hl.hl-orange { background: var(--pylon); color: var(--on-pylon); box-shadow: 0.08em 0.08em 0 0 var(--firstdown); transform: rotate(1.2deg); }
h1 em { font-family: var(--quote, Georgia, serif); font-style: italic; font-weight: 500; text-transform: none; letter-spacing: 0; color: var(--firstdown); }
h1 s { text-decoration-thickness: 0.12em; text-decoration-color: var(--loss); opacity: 0.75; }
h1 b { color: var(--pylon-ink); }
.deck em { font-style: italic; } .deck s { opacity: 0.7; } .deck .hl { background: var(--firstdown); color: var(--on-firstdown); padding: 0 0.2em; } .deck .hl-orange { background: var(--pylon); color: var(--on-pylon); }
.drawer .issues li.folder details { background: var(--bg); border: 1px solid var(--rule); padding: 0; }
.drawer .issues li.folder summary { list-style: none; cursor: pointer; display: grid; gap: 2px; padding: 10px 14px 10px 40px; min-height: 56px; position: relative; }
.drawer .issues li.folder summary::-webkit-details-marker { display: none; }
.drawer .issues li.folder summary::before { content: ""; position: absolute; left: 12px; top: 16px; width: 18px; height: 14px; border: 2px solid var(--pylon-ink); border-radius: 3px; box-shadow: inset 0 3px 0 0 var(--pylon-ink); }
.drawer .issues li.folder summary::after { content: "›"; position: absolute; right: 14px; top: 10px; font-size: 1.4rem; color: var(--ink-2); transform: rotate(90deg); transition: transform 0.15s; }
.drawer .issues li.folder details[open] summary::after { transform: rotate(-90deg); }
.drawer .issues li.folder summary .mono { color: var(--pylon-ink); }
.drawer .issues li.folder summary b { font-family: var(--display); font-weight: 800; font-size: 1.25rem; line-height: 1; text-transform: uppercase; }
.drawer .issues li.folder .issues { padding: 0 8px 8px; margin-top: 0; }
.drawer .issues li.folder .issues a { background: var(--surface); }
